def dedupe_consecutive(lst):
    result = []
    for x in lst:
        if not result or result[-1] != x:
            result.append(x)
    return result

def filter_out_none_and_empty(lst):
    result = []
    for x in lst:
        if x is None:
            continue
        if isinstance(x, (str, list, tuple, dict)) and len(x) == 0:
            continue
        result.append(x)
    return result

def chunk_fixed_size_pad(lst, k, pad):
    chunks = [lst[i:i + k] for i in range(0, len(lst), k)]
    if chunks and len(chunks[-1]) < k:
        chunks[-1] = chunks[-1] + [pad] * (k - len(chunks[-1]))
    return chunks

def sliding_window_list(lst, k):
    if k <= 0 or k > len(lst):
        return []
    return [lst[i:i + k] for i in range(len(lst) - k + 1)]

def sliding_window_sums(lst, k):
    if k <= 0 or k > len(lst):
        return []
    return [sum(lst[i:i + k]) for i in range(len(lst) - k + 1)]

def sliding_window_max(lst, k):
    if k <= 0 or k > len(lst):
        return []
    return [max(lst[i:i + k]) for i in range(len(lst) - k + 1)]

def running_min(lst):
    result = []
    current = None
    for i, x in enumerate(lst):
        if i == 0 or x < current:
            current = x
        result.append(current)
    return result

def rotate_right(lst, k):
    n = len(lst)
    if n == 0:
        return []
    k = k % n
    if k == 0:
        return list(lst)
    return lst[-k:] + lst[:-k]

def interleave_equal(a, b):
    result = []
    for x, y in zip(a, b):
        result.append(x)
        result.append(y)
    return result

def partition_even_odd(lst):
    evens = [x for x in lst if x % 2 == 0]
    odds = [x for x in lst if x % 2 != 0]
    return (evens, odds)

def partition_by_threshold(lst, t):
    below = [x for x in lst if x < t]
    at_or_above = [x for x in lst if x >= t]
    return (below, at_or_above)

def flatten_deep(nested):
    result = []
    for x in nested:
        if isinstance(x, list):
            result.extend(flatten_deep(x))
        else:
            result.append(x)
    return result

def pairwise_differences(lst):
    if len(lst) < 2:
        return []
    return [lst[i + 1] - lst[i] for i in range(len(lst) - 1)]

def longest_run_length(lst):
    if not lst:
        return 0
    longest = 1
    current = 1
    for i in range(1, len(lst)):
        if lst[i] == lst[i - 1]:
            current += 1
        else:
            current = 1
        longest = max(longest, current)
    return longest
